/** Actual native conversion replay against released Source transactions, not a scalar-only surrogate. */
@EventBusSubscriber(modid="vandorlabs")
public final class PropulsionEditorChecks {
 private static final java.util.Map<String,NativePropulsionBlock> BLOCKS=new java.util.LinkedHashMap<>();private static BlockEntityType<NativePropulsionEntity> TYPE;private static int checks,profiles;private static final BlockPos BASE=new BlockPos(7768,90,7768),SAVE=BASE.south(8);
 private static String phase(){return System.getProperty("vandorlabs.transmitterPhase","");}private static boolean enabled(){return phase().startsWith("propulsion-editor-");}private static void need(boolean yes,String message){checks++;if(!yes)throw new AssertionError("Propulsion editor "+message+" profile="+profiles);}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Registration{@SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent e){if(!enabled())return;e.register(Registries.BLOCK,h->{for(var d:PropulsionDefinition.values()){var block=new NativePropulsionBlock(d.id,BlockBehaviour.Properties.of().strength(5,10),()->TYPE,BLOCKS::get);BLOCKS.put(d.id,block);h.register(ResourceLocation.parse("vandorlabs:propulsion_editor_fixture_"+d.id),block);}});e.register(Registries.BLOCK_ENTITY_TYPE,h->{TYPE=BlockEntityType.Builder.of((p,s)->new NativePropulsionEntity(TYPE,p,s),BLOCKS.values().toArray(NativePropulsionBlock[]::new)).build(null);h.register(ResourceLocation.parse("vandorlabs:propulsion_editor_fixture"),TYPE);});}}
 private static BlockPos cell(Direction face,int size,int index){int right=PropulsionEmission.right(face.get3DDataValue()),up=PropulsionEmission.up(face.get3DDataValue()),x=size==1?0:index/size,y=size==1?0:index%size;return BASE.offset(PropulsionEmission.dx(right)*x+PropulsionEmission.dx(up)*y,PropulsionEmission.dy(right)*x+PropulsionEmission.dy(up)*y,PropulsionEmission.dz(right)*x+PropulsionEmission.dz(up)*y);}
 private static CompoundTag tag(JsonObject row){var tag=new CompoundTag();for(String key:new String[]{"ChannelLevel","ParticleLevel","ParticleThreshold","PropulsionSideTexture"})tag.putInt(key,row.get(key).getAsInt());for(String key:new String[]{"ManualOn","ChannelSignal","SignalBrightness","RedstoneInverted","PropulsionJoin","LightInitialized"})tag.putBoolean(key,row.get(key).getAsBoolean());var values=row.getAsJsonArray("channels");int[] channels=new int[values.size()];for(int i=0;i<channels.length;i++)channels[i]=values.get(i).getAsInt();tag.putIntArray("RedstoneChannels",channels);tag.putInt("RedstoneChannel",channels.length==0?0:channels[0]);return tag;}
 private static void write(ServerLevel w)throws Exception{w.getChunkAt(BASE);try(var lines=java.nio.file.Files.lines(java.nio.file.Path.of(System.getProperty("vandorlabs.propulsionShapeReference")))){for(String line:(Iterable<String>)lines::iterator){var row=JsonParser.parseString(line).getAsJsonObject();var block=BLOCKS.get(row.get("block").getAsString());var face=Direction.from3DDataValue(row.get("face").getAsInt());var before=row.getAsJsonArray("before");var after=row.getAsJsonArray("after");int size=before.size()==1?1:2,profile=row.get("profile").getAsInt();var owners=new java.util.ArrayList<NativePropulsionEntity>();for(int i=0;i<before.size();i++){var pos=cell(face,size,i);w.setBlock(pos,Blocks.AIR.defaultBlockState(),18);w.setBlock(pos,block.defaultBlockState().setValue(NativePropulsionBlock.FACING,face).setValue(NativePropulsionBlock.POWERED,true),18);var owner=(NativePropulsionEntity)w.getBlockEntity(pos);owner.loadWithComponents(tag(before.get(i).getAsJsonObject()),w.registryAccess());owners.add(owner);}if(profile!=11&&!(profile==10)){var draft=new NativePropulsionConfiguration.Draft(com.vandorlabs.redstone.ChannelList.of(37,41),profile!=0,3,profile!=1,profile%2==0,profile!=2,64,profile>=6,row.get("target").getAsInt(),profile%3==0,profile%3!=1,5);need(NativePropulsionConfiguration.apply(owners.getLast(),draft,null),"valid edit accepted");}for(int i=0;i<after.size();i++){var pos=cell(face,size,i);var expected=after.get(i).getAsJsonObject();var owner=(NativePropulsionEntity)w.getBlockEntity(pos);need(owner==owners.get(i)&&!owner.inert(),"same usable physical owner");need(owner.getBlockState().getBlock()==BLOCKS.get(expected.get("block").getAsString()),"Source shape");var actual=owner.saveWithoutMetadata(w.registryAccess());var wanted=tag(expected);for(String key:wanted.getAllKeys())need(wanted.get(key).equals(actual.get(key)),"Source field "+key+" expected="+wanted.get(key)+" actual="+actual.get(key)+" block="+row.get("block")+" face="+face+" profile="+profile+" member="+i);need(owner.getBlockState().getValue(NativePropulsionBlock.POWERED)==expected.get("powered").getAsBoolean(),"Source power profile="+profile);}for(int i=0;i<before.size();i++)w.setBlock(cell(face,size,i),Blocks.AIR.defaultBlockState(),18);profiles++;}}need(profiles==1944,"Source corpus coverage");wire();guards(w);}
 private static NativePropulsionSettingsEdit decoded(io.netty.buffer.ByteBuf bytes){try{return NativePropulsionSettingsEdit.decode(bytes);}finally{bytes.release();}}
 private static void wire(){for(int flags=0;flags<128;flags++)for(int count:new int[]{0,1,64}){int[] values=new int[count];for(int n=0;n<count;n++)values[n]=n+1;var d=new NativePropulsionConfiguration.Draft(com.vandorlabs.redstone.ChannelList.of(values),(flags&1)!=0,3,(flags&2)!=0,(flags&4)!=0,(flags&8)!=0,64,(flags&16)!=0,2,(flags&32)!=0,(flags&64)!=0,15);var source=new NativePropulsionSettingsEdit(BASE,17,d);var bytes=io.netty.buffer.Unpooled.buffer();try{source.encode(bytes);need(bytes.readableBytes()==21+4*count,"bounded wire bytes");need(decoded(bytes.copy()).equals(source),"all flags/channels wire roundtrip");for(int n=0;n<21;n++){boolean rejected=false;try{decoded(bytes.copy(0,n));}catch(IllegalArgumentException expected){rejected=true;}need(rejected,"truncated wire refused");}var trailing=bytes.copy();trailing.writeByte(0);boolean rejected=false;try{NativePropulsionSettingsEdit.decode(trailing);}catch(IllegalArgumentException expected){rejected=true;}finally{trailing.release();}need(rejected,"trailing wire refused");}finally{bytes.release();}}}
 private static void guards(ServerLevel w){w.setBlock(BASE,BLOCKS.get("rocket_thruster").defaultBlockState(),18);var owner=(NativePropulsionEntity)w.getBlockEntity(BASE);var tag=new CompoundTag();tag.putBoolean("ManualOn",true);tag.putBoolean("LightInitialized",true);owner.loadWithComponents(tag,w.registryAccess());var player=new net.neoforged.neoforge.common.util.FakePlayer(w,new com.mojang.authlib.GameProfile(java.util.UUID.fromString("d9ffb5ad-4fd7-459e-bb0c-5f703a26d94f"),"EngineEditor"));player.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);player.setPos(BASE.getX()+.5,BASE.getY()+.5,BASE.getZ()+.5);var use=player.gameMode.useItemOn(player,w,net.minecraft.world.item.ItemStack.EMPTY,net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(BASE),Direction.NORTH,BASE,false));need(use.consumesAction()&&owner.settings().data().manualMode()==2,"actual vanilla plain use cycles On to Stream like Source");var menu=new NativePropulsionMenu(null,17,owner);player.containerMenu=menu;var edit=new NativePropulsionConfiguration.Draft(com.vandorlabs.redstone.ChannelList.EMPTY,false,0,false,true,false,9,false,0,false,false,8);need(NativePropulsionMenu.apply(player,BASE,17,edit),"real menu survival edit");need(!NativePropulsionMenu.apply(player,BASE,18,edit),"wrong window refused");need(!NativePropulsionMenu.apply(player,BASE.east(),17,edit),"wrong owner position refused");var shape=new NativePropulsionConfiguration.Draft(com.vandorlabs.redstone.ChannelList.EMPTY,false,0,false,true,false,9,true,1,false,false,8);need(!NativePropulsionMenu.apply(player,BASE,17,shape),"survival shape refused");player.setGameMode(net.minecraft.world.level.GameType.CREATIVE);need(NativePropulsionMenu.apply(player,BASE,17,shape),"creative shape accepted");need(menu.stillValid(player)&&w.getBlockEntity(BASE)==owner,"menu preserves physical owner across shape replacement");player.setPos(BASE.getX()+20,BASE.getY(),BASE.getZ());need(!NativePropulsionMenu.apply(player,BASE,17,edit),"distance refused");player.setPos(BASE.getX()+.5,BASE.getY()+.5,BASE.getZ()+.5);player.setGameMode(net.minecraft.world.level.GameType.SPECTATOR);need(!NativePropulsionMenu.apply(player,BASE,17,edit),"spectator refused");player.setGameMode(net.minecraft.world.level.GameType.CREATIVE);w.setBlock(BASE,Blocks.AIR.defaultBlockState(),18);w.setBlock(BASE,BLOCKS.get("rocket_thruster").defaultBlockState(),18);need(!NativePropulsionMenu.apply(player,BASE,17,edit),"stale replaced tile identity refused");w.setBlock(BASE,Blocks.AIR.defaultBlockState(),18);}

 @SubscribeEvent public static void started(ServerStartedEvent event){if(!enabled())return;try{write(event.getServer().overworld());System.out.println("[vandorlabs][propulsion-editor] write PASS profiles="+profiles+" checks="+checks);}catch(Throwable failure){System.err.println("[vandorlabs][propulsion-editor] FAIL "+failure);failure.printStackTrace();}finally{event.getServer().halt(false);}}
}
